create table if not exists public.shows_app_2026_research_calendar (
  control_id text primary key,
  profile_id text,
  event_label text not null,
  event_start date,
  event_end date,
  schedule_text text,
  date_confidence text not null check (date_confidence in ('EXACT','RANGE','RECURRING','ESTIMATED','TBD')),
  disposition text not null check (disposition in ('PURSUE','WATCH','HISTORICAL','BOOKED','WAITLIST','SUPPRESS')),
  priority text not null check (priority in ('HIGH','MEDIUM','LOW')),
  research_classification text not null,
  profile_relation text,
  evidence_summary text not null,
  source_basis text not null,
  source_archive_file_id text not null,
  include_in_calendar boolean not null default true,
  active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (event_end is null or event_start is null or event_end >= event_start)
);

create index if not exists shows_app_2026_research_calendar_start_idx
  on public.shows_app_2026_research_calendar(event_start);
create index if not exists shows_app_2026_research_calendar_profile_idx
  on public.shows_app_2026_research_calendar(profile_id);
create index if not exists shows_app_2026_research_calendar_active_idx
  on public.shows_app_2026_research_calendar(active,include_in_calendar);

alter table public.shows_app_2026_research_calendar enable row level security;

comment on table public.shows_app_2026_research_calendar is
  'Reconciled 2026 operational research overlay recovered from the September 2026 Layer 3 show-audit archive. Separate from canonical profile/history and rebook workflow tables.';

on conflict (control_id) do update set
  profile_id=excluded.profile_id,
  event_label=excluded.event_label,
  event_start=excluded.event_start,
  event_end=excluded.event_end,
  schedule_text=excluded.schedule_text,
  date_confidence=excluded.date_confidence,
  disposition=excluded.disposition,
  priority=excluded.priority,
  research_classification=excluded.research_classification,
  profile_relation=excluded.profile_relation,
  evidence_summary=excluded.evidence_summary,
  source_basis=excluded.source_basis,
  source_archive_file_id=excluded.source_archive_file_id,
  include_in_calendar=excluded.include_in_calendar,
  active=excluded.active,
  updated_at=now();
